package br.com.cambioclaro.app;
import android.app.*;
import android.os.*;
import android.content.*;
import android.net.Uri;
import android.widget.*;
import android.view.*;
public final class SettingsActivity extends Activity {
    private UiStyle style;private LinearLayout body;private FxCurrency currency;private Runnable updateStatus;
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);style.text(t);t.setPadding(0,dp(10),0,dp(10));body.addView(t);return t;}
    private void button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setMinHeight(dp(48));style.button(b);body.addView(b);b.setOnClickListener(v->action.run());}
    @Override public void onCreate(Bundle state){Preferences.theme(this);super.onCreate(state);style=new UiStyle(this);currency=RateStore.active(this);
        ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(22),dp(20),dp(22),dp(25));style.root(scroll);style.root(body);scroll.addView(body);setContentView(scroll);
        UiBars.apply(this,Preferences.light(this));
        scroll.setOnApplyWindowInsetsListener((v,in)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=in.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}return in;});
        button("← Voltar",()->finish());text("Preferências e privacidade",24);
        button("Aparência: "+(Preferences.light(this)?"clara":"escura"),()->new AlertDialog.Builder(this).setTitle("Aparência").setItems(new String[]{"Escuro","Claro"},(d,w)->{Preferences.prefs(this).edit().putString("theme",new String[]{"dark","light"}[w]).apply();recreate();CambioWidget.renderAll(this,null);}).show());
        text("Alertas da PTAX",21);text("Escolha uma moeda e um limite em reais por unidade. Cada alerta avisa uma vez e precisa ser salvo novamente para rearmar. Consulta em segundo plano todos os dias, a cada 30 minutos, sujeita às restrições do Android. A PTAX é diária; não é monitoramento de mercado ao vivo.",15);
        Spinner currencies=new Spinner(this);currencies.setContentDescription("Moeda do alerta");style.spinner(currencies,FxCurrency.values());currencies.setSelection(currency.ordinal());body.addView(currencies);
        Spinner direction=new Spinner(this);direction.setContentDescription("Direção do limite");style.spinner(direction,new String[]{"Igual ou acima do limite","Igual ou abaixo do limite"});body.addView(direction);
        text("Limite em R$ por 1 unidade da moeda",15);EditText value=new EditText(this);style.input(value);value.setHint("Ex.: 5,50");value.setContentDescription("Limite de cotação em reais");value.setInputType(8194);value.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(15)});body.addView(value);
        TextView stateText=text("",14);
        updateStatus=()->{boolean on=Alerts.enabled(this,currency);stateText.setText(!on?"Alerta desativado":Alerts.prefs(this).getBoolean(currency.name()+"_fired",false)?"Alerta já enviado. Salve novamente para rearmar.":Alerts.permitted(this)?"Alerta ativo • aguardando próxima consulta":"Alerta salvo, mas notificações estão bloqueadas nas configurações do Android.");};
        Runnable show=()->{currency=(FxCurrency)currencies.getSelectedItem();boolean on=Alerts.enabled(this,currency);value.setText(Alerts.prefs(this).getString(currency.name()+"_value","").replace('.',','));direction.setSelection(Alerts.prefs(this).getBoolean(currency.name()+"_above",true)?0:1);updateStatus.run();};
        currencies.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){show.run();}});
        button("Salvar / rearmar alerta",()->{try{Alerts.save(this,currency,value.getText().toString(),direction.getSelectedItemPosition()==0);show.run();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},12);CambioWidget.schedule(this);}catch(IllegalArgumentException e){value.setError(e.getMessage());new AlertDialog.Builder(this).setTitle("Limite inválido").setMessage(e.getMessage()).setPositiveButton("OK",null).show();}});
        button("Desativar alerta desta moeda",()->{Alerts.disable(this,currency);show.run();});
        button("Permissão de notificações no Android",()->startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName())));
        text("Alertas de mercado",21);text("Configure um limite para a cotação de mercado (venda/ask) da AwesomeAPI. O alerta avisa uma vez e precisa ser salvo novamente para rearmar. Só dispara com cotação recebida há no máximo 10 minutos. No segundo plano, o Android pode adiar a consulta; não é fluxo contínuo nem garantia de preço em tempo real.",15);
        Spinner marketCurrencies=new Spinner(this);marketCurrencies.setContentDescription("Moeda para alerta de mercado");style.spinner(marketCurrencies,FxCurrency.values());marketCurrencies.setSelection(currency.ordinal());body.addView(marketCurrencies);
        Spinner marketDirection=new Spinner(this);marketDirection.setContentDescription("Direção do alerta de mercado");style.spinner(marketDirection,new String[]{"Igual ou acima do limite","Igual ou abaixo do limite"});body.addView(marketDirection);
        text("Limite de mercado em R$ por 1 unidade",15);EditText marketValue=new EditText(this);style.input(marketValue);marketValue.setHint("Ex.: 5,50");marketValue.setContentDescription("Limite de cotação de mercado em reais");marketValue.setInputType(8194);marketValue.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(15)});body.addView(marketValue);
        TextView marketState=text("",14);Runnable showMarket=()->{FxCurrency selected=(FxCurrency)marketCurrencies.getSelectedItem();boolean on=MarketAlerts.enabled(this,selected);marketValue.setText(MarketAlerts.prefs(this).getString(selected.name()+"_value","").replace('.',','));marketDirection.setSelection(MarketAlerts.prefs(this).getBoolean(selected.name()+"_above",true)?0:1);marketState.setText(!on?"Alerta de mercado desativado":MarketAlerts.prefs(this).getBoolean(selected.name()+"_fired",false)?"Alerta de mercado já enviado. Salve novamente para rearmar.":"Alerta ativo · fonte AwesomeAPI ask · aguardando consulta válida.");};
        marketCurrencies.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){showMarket.run();}});
        button("Salvar / rearmar alerta de mercado",()->{FxCurrency selected=(FxCurrency)marketCurrencies.getSelectedItem();try{MarketAlerts.save(this,selected,marketValue.getText().toString(),marketDirection.getSelectedItemPosition()==0);showMarket.run();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},13);}catch(IllegalArgumentException e){marketValue.setError(e.getMessage());new AlertDialog.Builder(this).setTitle("Limite inválido").setMessage(e.getMessage()).setPositiveButton("OK",null).show();}});
        button("Desativar alerta de mercado desta moeda",()->{MarketAlerts.disable(this,(FxCurrency)marketCurrencies.getSelectedItem());showMarket.run();});showMarket.run();
        text("Atualizações pelo GitHub",21);text("O app verifica Releases públicas automaticamente quando há rede e, em segundo plano, o Android pode executar a checagem em intervalos de cerca de 12 horas. O Android controla o horário para poupar bateria. Ao encontrar uma versão, o app avisa; para instalar, você baixa e confirma na tela segura do Android. A instalação silenciosa não é permitida.",15);
        TextView githubStatus=text("Aguardando verificação.",14);
        button("Verificar atualização agora",()->{githubStatus.setText("Consultando Releases do GitHub…");GithubUpdates.checkAsync(this,(message,available)->runOnUiThread(()->githubStatus.setText(message+(available?" Toque em Baixar e instalar.":""))));});
        button("Permitir instalação pelo Câmbio Claro",()->{try{startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));}catch(Exception e){new AlertDialog.Builder(this).setMessage("Abra Configurações do Android > Instalar apps desconhecidos > Câmbio Claro.").setPositiveButton("OK",null).show();}});
        button("Baixar e instalar atualização",()->{if(Build.VERSION.SDK_INT>=26&&!getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(this).setTitle("Permissão do Android necessária").setMessage("Permita que o Câmbio Claro instale atualizações. Depois volte aqui e toque novamente em Baixar e instalar.").setPositiveButton("Abrir configuração",(d,w)->{try{startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));}catch(Exception ignored){}}).setNegativeButton("Cancelar",null).show();return;}githubStatus.setText("Baixando e validando APK…");GithubUpdates.downloadAndInstall(this,(message,available)->runOnUiThread(()->githubStatus.setText(message)));});
        button("Permitir notificações de versão",()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},14);else startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));});
        text("Bolsa de valores",21);text("PETR4, VALE3, ITUB4 e MGLU3 são consultadas sem chave. Para o Ibovespa, configure o endereço HTTPS de um servidor que guarda BRAPI_TOKEN. Não digite sua chave neste aplicativo. Sem servidor configurado, o índice permanece indisponível.",15);
        EditText backendUrl=new EditText(this);style.input(backendUrl);backendUrl.setHint("https://seu-servidor.example");backendUrl.setText(Stocks.backend(this));backendUrl.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);backendUrl.setSingleLine(true);backendUrl.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(255)});body.addView(backendUrl);
        button("Salvar servidor HTTPS",()->{try{Stocks.backend(this,backendUrl.getText().toString());Toast.makeText(this,"Endereço salvo. Abra o app para consultar o Ibovespa.",Toast.LENGTH_LONG).show();}catch(IllegalArgumentException ex){backendUrl.setError(ex.getMessage());}});
        button("Remover servidor",()->{Stocks.backend(this,"");backendUrl.setText("");Toast.makeText(this,"Servidor removido.",Toast.LENGTH_SHORT).show();});
        text("Privacidade",21);text("O app guarda no armazenamento privado o último diagnóstico técnico: modelo e versão do Android, horário, tipo da falha, mensagem técnica e pilha de chamadas. Falhas de consultas e crashes podem ser registrados. O relatório não inclui cotações, valores digitados nem limites de alertas. Revise mensagens técnicas antes de compartilhar. No botão Diagnóstico da tela inicial, você pode consultar, copiar, compartilhar, enviar ao suporte ou apagar o registro. Nada é enviado automaticamente.",15);text("O app consulta AwesomeAPI, Banco Central e as ações públicas da brapi por HTTPS. Se você configurar um servidor próprio para o Ibovespa, esse servidor receberá a consulta do índice. A chave brapi não fica no APK nem no armazenamento do app. Não há anúncios ou rastreadores.",15);
        text("Cotações, favoritas, aparência, configuração dos widgets e limites de alerta ficam no armazenamento privado do aplicativo no aparelho. Não enviamos seus valores digitados, favoritas ou limites para o Banco Central. Notificações são geradas localmente. A consulta em segundo plano ocorre quando há alertas ativos ou widgets; o Android pode adiá-la. A desinstalação remove esses dados locais.",15);
        text("Suporte e contato sobre privacidade: brenoaugustoalves@gmail.com\nAo enviar um e-mail, as informações que você escrever serão tratadas pelo seu provedor de e-mail e pelo destinatário para responder ao pedido. Nenhum diagnóstico é anexado automaticamente.",15);
        button("Enviar e-mail ao suporte",()->{try{startActivity(new Intent(Intent.ACTION_SENDTO,Uri.parse("mailto:brenoaugustoalves@gmail.com?subject=Suporte%20C%C3%A2mbio%20Claro")));}catch(ActivityNotFoundException e){new AlertDialog.Builder(this).setMessage("Escreva para brenoaugustoalves@gmail.com usando seu serviço de e-mail.").setPositiveButton("OK",null).show();}});
        text("Versão 1.8.0 • política atualizada em 02/11/2026\nDados: Banco Central do Brasil, AwesomeAPI e brapi. Aplicativo independente.",13);
    }
    @Override public void onResume(){super.onResume();if(updateStatus!=null)updateStatus.run();}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==14){boolean ok=Build.VERSION.SDK_INT<33||checkSelfPermission("android.permission.POST_NOTIFICATIONS")==android.content.pm.PackageManager.PERMISSION_GRANTED;Toast.makeText(this,ok?"Notificações de versão permitidas.":"Notificações de versão bloqueadas nas configurações do Android.",Toast.LENGTH_LONG).show();if(ok)GithubUpdates.checkAsync(this,(message,available)->{});return;}if(r==12||r==13){if(updateStatus!=null)updateStatus.run();boolean ok=Alerts.permitted(this);Toast.makeText(this,ok?"Notificações permitidas. O alerta será avaliado na próxima consulta.":"Notificações bloqueadas. Você pode permitir nas configurações do Android.",Toast.LENGTH_LONG).show();if(ok)CambioWidget.schedule(this);}}
}
